import operator
import json
from contextlib import contextmanager
from taf.ccs.aashell import aashell as AaShellLib
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class PythonAaShellLib(AaShellLib):
    def __init__(self, **kwargs):
        super(PythonAaShellLib, self).__init__(**kwargs)
        self._aliases = {}

    def set_alias(self, alias, obj):
        self._aliases[alias] = obj

    def get_alias_value(self, alias):
        return self._aliases[alias]


@contextmanager
def aashell_context(alias):
    aashell_lib = PythonAaShellLib()
    aashell_lib.create_aashell_cli(name=alias)
    aashell_lib.setup(alias=alias)
    yield aashell_lib
    aashell_lib.teardown(alias=alias)


class AaShellManager:
    def __init__(self):
        pass

    def get_resource_usage(self, **kwargs):
        alias = kwargs.get("alias", "default")
        detailed = kwargs.get('detailed', True)
        with aashell_context(alias=alias) as aashell:
            return aashell.get_resources_usage(name=alias, detailed=detailed)

    def should_be_equal_as_resources(self, **kwargs):
        alias = kwargs.get("alias", "default")
        resources_usage1 = kwargs["resource_usage"]
        exclude = kwargs.get("exclude", None)
        detailed = kwargs.get('detailed', True)
        fail_on_not_released_resources = kwargs.get("fail_on_not_released_resources", True)
        with aashell_context(alias=alias) as aashell:
            resources_usage2 = aashell.get_resources_usage(name=alias, detailed=detailed)
            try:
                return aashell.should_be_equal_as_resources(resources_usage1=resources_usage1,
                                                            resources_usage2=resources_usage2, exclude=exclude)
            except AssertionError:
                logger.warn('Resources Before {}'.format(resources_usage1))
                logger.warn('Resources After {}'.format(resources_usage2))

                output_diff = self._compare_trees(resources_usage1, resources_usage2)

                if fail_on_not_released_resources:
                    raise AssertionError('Resources before and after differ!\n{}'.format(str(output_diff)))
                else:
                    logger.warn('Resources before and after differ!\n{}'.format(str(output_diff)))

    def should_all_be_zero(self, **kwargs):
        resources_usage = kwargs["resource_usage"]
        path_regex = kwargs.get("path_regex", None)
        fail_on_not_released_resources = kwargs.get("fail_on_not_released_resources", True)
        alias = kwargs.get("alias", "default")
        with aashell_context(alias=alias) as aashell:
            try:
                return aashell.should_all_be_zero(resources_usage=resources_usage, regex=path_regex)
            except AssertionError:
                logger.warn('Resources Gathered {}'.format(resources_usage))
                if fail_on_not_released_resources:
                    raise AssertionError('Resources gathered is not equal to zero!')
                else:
                    logger.warn('Resources gathered is not equal to zero!')

    def _compare_trees(self, data1, data2):
        data = self._do_compare(data1, data2, "", "", path="")
        tree_data = self._find_diff_tree(data1, data2)
        return {"compared_data": data, "diff_tree": tree_data}

    def _find_diff_tree(self, data1, data2):
        d1_keys = set(data1.keys())
        d2_keys = set(data2.keys())
        shared_keys = d1_keys.intersection(d2_keys)

        modified = {o: (data1[o], data2[o]) for o in shared_keys if data1[o] != data2[o]}
        return modified

    def _do_compare(self, data1, data2, data1_name, data2_name, path="", diff_data=[]):

        if operator.eq(data1, data2) and not path:
            logger.info("Both before and after resources_usage values are the same!")
        else:
            if isinstance(data1, dict) and isinstance(data2, dict):
                self._compare_dict(data1, data2, data1_name, data2_name, path)
            elif isinstance(data1, list) and isinstance(data2, list):
                self._compare_list(data1, data2, data1_name, data2_name, path)
            else:
                if data1 != data2:
                    value_err = "%s%s : %s != %s" \
                                % (data1_name, path, data1, data2)
                    diff_data.append(value_err)
                    # logger.warn(value_err)
        return (diff_data)

    def _compare_dict(self, data1, data2, data1_name, data2_name, path):
        old_path = path
        for k in data1.keys():
            path = old_path + "[%s]" % k
            if k not in data2:
                key_err = "dict1: Key %s%s not in %s\n" % (data1_name, path, data2_name)
                # logger.warn(key_err)
            else:
                self._do_compare(data1[k], data2[k], data1_name, data2_name, path)
        for k in data2.keys():
            path = old_path + "[%s]" % k
            if k not in data1:
                key_err = "dict2: Key %s%s not in %s\n" % (data2_name, path, data1_name)
                # logger.warn(key_err)

    def _compare_list(self, data1, data2, data1_name, data2_name, path):
        data1_length = len(data1)
        data2_length = len(data2)
        old_path = path
        if data1_length != data2_length:
            value_err = "list : No: of items in %s%s (%s) not same as %s%s (%s)\n" \
                        % (data1_name, path, data1_length, data2_name, path, data2_length)
            # logger.warn(value_err)
        for index, item in enumerate(data1):
            path = old_path + "[%s]" % index
            try:
                self._do_compare(data1[index], data2[index], data1_name, data2_name, path)
            except IndexError:
                pass